// Generated by oapi-clientgen. Do not edit:
// `oapi-clientgen generate` rewrites this file, so edits are lost
// silently. Change the template in oapi-clientgen instead.
// Resilience for the pokedex client: timeout, retry, circuit
// breaker and the identifying headers. The defaults match the Go
// client in api/client.go, because both
// clients failing the same way is the point.
//
// Breaking is off in both until asked for: `breaker: new Breaker()`
// here, `WithBreaker()` in Go.
//
//   import { createClient, listThings } from '@christopherscot/pokedex-client'
//   const client = createClient({ baseUrl: 'https://pokedex', name: 'my-service' })
//   const { data, error } = await listThings({ client })
//
// Everything below is generator-agnostic: it wraps `fetch` and knows
// nothing about how the operations were generated. Swapping the
// generator means changing the import and the one adapter call at
// the bottom of this file.
// /index.ts, not .ts: generated/client is a DIRECTORY, so a published
// client names its entry file where the others name themselves.
import { createClient as createGeneratedClient, createConfig } from './generated/client/index.ts'

// Read from package.json rather than hardcoded: the header cannot then
// disagree with the version a consumer installed, which is the one
// that matters once this is on npm.
import pkg from './package.json' with { type: 'json' }

export const ClientVersion: string = pkg.version
export const ClientVersionHeader = 'Client-Version'

// Required by createClient and createResilientFetch. No X- prefix on
// either: RFC 6648 deprecated it in 2012.
export const ClientNameHeader = 'Client-Name'

export interface RetryPolicy {
  backoffs(): number[]
  retry(req: Request, res: Response | undefined, err: unknown): boolean
}

export interface ClientOptions {
  baseUrl: string
  /** The CALLER's own service name, sent as Client-Name. Required
   *  because the cost of omitting it falls on whoever operates the
   *  service being called. */
  name: string
  /** Bounds a single attempt; a retry gets its own, so a retried call
   *  can run for longer than this. Pass your own `signal` to bound the
   *  whole call, retries and backoffs included. */
  timeoutMs?: number
  /** Default singleRetry. */
  policy?: RetryPolicy
  /** Omit to disable circuit breaking. */
  breaker?: Breaker
  /** Bounds how long a server can park this client. */
  maxRetryAfterMs?: number
  /** What actually goes to the network. Defaults to global fetch.
   *
   *  It sits UNDER the retry loop: a supplied fetch replaces the
   *  network, not the resilience. */
  fetch?: typeof globalThis.fetch
}

/** What one request says about the service's health.
 *
 *  Three values, not two: "this tells us nothing" is different from
 *  "this went fine". A breaker that treats them alike lets an ignored
 *  outcome erase a run of real failures - a service answering 500 on
 *  one route and 501 on another would never trip. */
export type Outcome = 'healthy' | 'unwell' | 'ignore'

/** A permanent statement about THIS REQUEST rather than evidence
 *  about the service: the route is not implemented (501), or the
 *  HTTP version is not spoken (505). Neither changes after a
 *  cooldown, so neither is worth a retry or a place in the count. */
function permanentProtocolError(status: number): boolean {
  return status === 501 || status === 505
}

function classify(
  res: Response | undefined,
  err: unknown,
  caller: AbortSignal | undefined
): Outcome {
  if (err !== undefined) {
    // Whose signal aborted? Our own per-attempt timeout arrives as
    // an abort too, and a service too slow to answer within it IS
    // unwell - that is a case the breaker exists for. So the
    // question is not what the error says, it is whether the
    // CALLER's signal is the one that fired.
    return caller?.aborted === true ? 'ignore' : 'unwell'
  }
  if (res === undefined) return 'ignore'
  if (permanentProtocolError(res.status)) return 'ignore'
  return res.status >= 500 ? 'unwell' : 'healthy'
}

/** A backoff that a caller can cut short. Rejects with the signal's
 *  own reason, so an aborted call fails the way fetch would have. */
function abortableDelay(ms: number, signal?: AbortSignal | null): Promise<void> {
  if (signal?.aborted === true) return Promise.reject(signal.reason)
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort)
      resolve()
    }, ms)
    const onAbort = () => {
      clearTimeout(timer)
      reject(signal?.reason)
    }
    signal?.addEventListener('abort', onAbort, { once: true })
  })
}

// A POST may already have applied, so retrying it can create a second thing.
const IDEMPOTENT = new Set(['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE'])

function retryable(req: Request, res: Response | undefined, err: unknown): boolean {
  if (!IDEMPOTENT.has(req.method)) return false
  if (err !== undefined) return true
  if (res === undefined) return false
  // Same carve-out the breaker makes: a permanently unimplemented
  // route does not become implemented on the next attempt.
  if (permanentProtocolError(res.status)) return false
  return res.status === 429 || res.status >= 500
}

// One retry, after a short pause. The default.
export const singleRetry: RetryPolicy = {
  backoffs: () => [1000],
  retry: retryable,
}

// Several jittered attempts, for a slow-but-not-broken dependency. Jitter
// so a fleet of callers does not retry in lockstep.
export const exponentialRetry: RetryPolicy = {
  backoffs: () => {
    const out: number[] = []
    let next = 100
    for (let i = 0; i < 5; i++) {
      out.push(next + ((Math.random() * 2 - 1) * 25) / 100 * next)
      next *= 2
    }
    return out
  },
  retry: retryable,
}

export const noRetry: RetryPolicy = { backoffs: () => [], retry: () => false }

/** The server's own answer, and whether it asked for longer than we
 *  will wait. `tooLong` means STOP: the caller must give up rather
 *  than substitute a shorter wait of its own. */
// The three date formats RFC 9110 requires a recipient to accept, and
// exactly what Go's http.ParseTime takes. Day and month names are
// spelled out because V8 ignores a bogus weekday: Date.parse reads
// 'Xyz, 21 Oct 2025 07:28:00 GMT' happily, Go does not.
const DAY = '(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)'
const DAYLONG = '(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)'
const MON = '(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)'
const HMS = '(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]'

const IMF_FIXDATE = new RegExp(`^${DAY}, [0-3][0-9] ${MON} [0-9]{4} ${HMS} GMT$`)
const RFC850 = new RegExp(`^${DAYLONG}, [0-3][0-9]-${MON}-[0-9]{2} ${HMS} GMT$`)
const ASCTIME = new RegExp(`^${DAY} ${MON} [ 0-3]?[0-9] ${HMS} [0-9]{4}$`)

function isHTTPDate(t: string): boolean {
  return IMF_FIXDATE.test(t) || RFC850.test(t) || ASCTIME.test(t)
}

export function retryAfterMs(
  res: Response | undefined,
  maxMs: number
): { ms?: number; tooLong: boolean } {
  const v = res?.headers?.get('retry-after')
  if (!v) return { tooLong: false }

  // Matched on shape, because Number() and Date.parse are far looser
  // than RFC 9110: Date.parse reads '1.5', '-5' and ' 5 .5' as dates
  // in 2001, and Number() takes '0x10' and '1e3'. Anything unmatched
  // falls back to the policy's own backoff.
  let ms
  const t = v.trim()
  if (/^\+?[0-9]+$/.test(t)) {
    ms = Number(t) * 1000
  } else if (isHTTPDate(t)) {
    const when = Date.parse(t)
    if (Number.isNaN(when)) return { tooLong: false }
    ms = Math.max(0, when - Date.now())
  } else {
    return { tooLong: false }
  }
  // Over the cap means STOP, not "wait maxMs instead"; the Go client's
  // retryAfter carries the reasoning.
  return ms > maxMs ? { tooLong: true } : { ms, tooLong: false }
}

export class CircuitOpenError extends Error {
  constructor() {
    super('circuit open')
    this.name = 'CircuitOpenError'
  }
}

/** When a dependency has failed enough to stop asking.
 *
 *  A rate over a window rather than a run of consecutive failures: a
 *  dependency answering two requests in three with a 500 is one to
 *  shed load from, and under a consecutive count the one success in
 *  three clears the run forever. Measured per REQUEST, so one that
 *  exhausted its retries counts once. */
export interface BreakerPolicy {
  /** How far back the rate is measured. */
  windowMs: number
  /** How many requests the window needs before a rate means
   *  anything. Below it the circuit stays closed: two failures out of
   *  two is 100% and says almost nothing. */
  minRequests: number
  /** The share of failed requests that opens the circuit, as a whole
   *  number out of 100. */
  failPercent: number
  /** How long an open circuit waits before letting one request
   *  through to find out whether the dependency is back. */
  cooldownMs: number
}

/** What `new Breaker()` uses when given nothing.
 *
 *  50% where wag's hystrix default is 90%: that figure suits a window
 *  holding thousands of requests, where a service at 89% errors is
 *  still serving hundreds. At the request rates these clients see, a
 *  dependency failing half of what it is asked is unwell. */
export const defaultBreakerPolicy: BreakerPolicy = {
  windowMs: 10000,
  minRequests: 20,
  failPercent: 50,
  cooldownMs: 30000,
}

/** One request's contribution to the window. */
interface Attempt {
  at: number
  failed: boolean
}

export class Breaker {
  #outcomes: Attempt[] = []
  #open = false
  #probing = false
  #openedAt = 0
  readonly policy: BreakerPolicy

  /** Partial policies are filled from defaultBreakerPolicy, so a
   *  field added later keeps its default rather than becoming
   *  undefined. */
  constructor(policy: Partial<BreakerPolicy> = {}) {
    this.policy = { ...defaultBreakerPolicy, ...policy }
  }

  /** Whether this policy asks for nothing. A zero window or
   *  minRequests describes no measurement, and a zero failPercent
   *  would otherwise read as "open at no failures at all" - the
   *  opposite of what leaving it unset means. */
  #off(): boolean {
    const p = this.policy
    return p.windowMs <= 0 || p.minRequests <= 0 || p.failPercent <= 0
  }

  allow(): boolean {
    if (this.#off()) return true
    if (!this.#open) return true
    // Open. One caller past the cooldown gets through to find out
    // whether the dependency is back; everyone else waits for its
    // verdict rather than joining it.
    if (!this.#probing && Date.now() - this.#openedAt > this.policy.cooldownMs) {
      this.#probing = true
      return true
    }
    return false
  }

  /** Trims the window and reports the failure percentage in it, and
   *  whether there were enough requests for that to mean anything. */
  #rate(now: number): { pct: number; enough: boolean } {
    const cut = now - this.policy.windowMs
    let keep = 0
    while (keep < this.#outcomes.length && this.#outcomes[keep]!.at < cut) keep++
    this.#outcomes = this.#outcomes.slice(keep)

    if (this.#outcomes.length < this.policy.minRequests) return { pct: 0, enough: false }
    const failed = this.#outcomes.filter((a) => a.failed).length
    return { pct: Math.floor((failed * 100) / this.#outcomes.length), enough: true }
  }

  /** Takes the probe slot back if this request held it, adds this
   *  request to the window, and reads the rate. */
  record(o: Outcome): void {
    if (this.#off()) return
    const probe = this.#probing
    this.#probing = false

    // Each outcome declares what it PROVED, and the window below
    // takes only those. An outcome added later has to say so to count
    // either way, and silence keeps it out of the rate rather than
    // landing in it as a success.
    let recovered = false
    let counted = false
    switch (o) {
      case 'healthy':
        recovered = true
        counted = true
        break
      case 'unwell':
        counted = true
        break
      case 'ignore':
        // Says nothing about the dependency, so it is not a data
        // point: a 501 on one route or a caller that gave up should
        // neither open the circuit nor argue against opening it.
        break
    }

    const now = Date.now()
    if (counted) this.#outcomes.push({ at: now, failed: !recovered })

    // A probe that did not prove recovery spends its slot and costs
    // a full cooldown, or an open circuit hands a fresh probe to
    // every caller the moment the first reports back.
    if (probe && !recovered) {
      this.#openedAt = now
      return
    }
    // The probe found it answering. The failures that opened the
    // circuit are what it was judged on, so they go with it - held,
    // they would re-open it on the next read.
    if (probe && recovered) {
      this.#open = false
      this.#outcomes = []
      return
    }

    // Only a request that said something can move the circuit. An
    // ignored one adds no data point, so re-reading the rate for it
    // would re-arm the cooldown on evidence that has not changed -
    // pushing recovery further away every time a caller cancels.
    if (!counted) return

    const { pct, enough } = this.#rate(now)
    if (!enough) return
    if (pct >= this.policy.failPercent) {
      // Re-armed on every failing read, not only the first, so the
      // cooldown is measured from the last failure rather than the
      // one that opened the circuit.
      this.#open = true
      this.#openedAt = now
    } else {
      this.#open = false
    }
  }
}

/**
 * The transport on its own: a `fetch` that times out, retries, obeys
 * Retry-After and trips a breaker.
 *
 * Exported separately from createClient because setConfig takes a
 * fetch, not a client - so an app configuring the module-level client
 * can reach the retries without building a second one.
 *
 * Compose it with whatever else the transport has to do:
 *
 *   fetch: (input, init) => resilientFetch(withAuth(input, init))
 */
export function createResilientFetch({
  // CALLER's own service name, sent as Client-Name.
  name,
  timeoutMs = 5000,
  policy = singleRetry,
  breaker,
  maxRetryAfterMs = 30000,
  fetch: send,
}: Omit<ClientOptions, 'baseUrl'>) {
  return async (input: RequestInfo | URL, init?: RequestInit) => {
    const req = new Request(input, init)
    // Whichever signals the caller actually gave us, combined.
    //
    // Not req.signal: Request always synthesises one, so it cannot
    // tell "the caller passed a signal" from "the caller did not".
    // Not init.signal alone either - fetch(request) with no init is
    // the shape the generated adapter uses, and that dropped the
    // caller's cancellation on the likeliest path. Both can be
    // present, and choosing one silently ignores the other.
    const given = [
      init?.signal,
      input instanceof Request ? input.signal : undefined,
    ].filter((s): s is AbortSignal => s != null)
    const caller =
      given.length === 0 ? undefined : given.length === 1 ? given[0] : AbortSignal.any(given)
    req.headers.set(ClientVersionHeader, ClientVersion)
    if (name) req.headers.set(ClientNameHeader, name)

    if (breaker && !breaker.allow()) throw new CircuitOpenError()

    const backoffs = policy.backoffs()
    let res: Response | undefined
    let err: unknown

    // try/finally so EVERY exit reports back, including the abort
    // that abortableDelay throws. allow() hands out the half-open
    // probe and only record() takes it back: a probe that leaves
    // without reporting leaves the breaker believing it is still in
    // flight, and allow() then refuses everyone for good. Wedged
    // closed does not heal.
    try {
      for (let attempt = 0; ; attempt++) {
        err = undefined
        try {
          // The caller's own signal is combined with the per-attempt
          // timeout rather than replaced by it: a caller that aborts
          // must stop the whole call, not just lose one attempt.
          // Resolved per request, not captured when this factory
          // ran: a consumer that builds the client at module load and
          // installs an interceptor afterwards - msw, a fetch
          // instrumentation - would otherwise keep the global from
          // before the patch.
          res = await (send ?? globalThis.fetch)(req.clone(), {
            signal: caller
              ? AbortSignal.any([caller, AbortSignal.timeout(timeoutMs)])
              : AbortSignal.timeout(timeoutMs),
          })
        } catch (e) {
          err = e
          res = undefined
        }
        if (attempt >= backoffs.length || !policy.retry(req, res, err)) break

        // The server's Retry-After wins over the policy's backoff.
        const after = retryAfterMs(res, maxRetryAfterMs)
        if (after.tooLong) {
          // It asked for longer than we will wait. Hand the response
          // back rather than retrying sooner than it said.
          break
        }
        const wait = after.ms ?? backoffs[attempt]
        // Wait, unless the caller has already given up. A bare
        // setTimeout would hold the backoff for the server's full
        // Retry-After and then retry on behalf of nobody.
        await abortableDelay(wait, caller)
      }

    } finally {
      breaker?.record(classify(res, err, caller))
    }

    if (err !== undefined) throw err
    if (res === undefined) {
      // Unreachable: the loop leaves res set unless it also set err,
      // which threw above. Stated rather than asserted, so the day
      // someone adds a path out of the loop they get this instead of
      // a client handed undefined.
      throw new Error('request produced neither a response nor an error')
    }
    return res
  }
}

/** A configured transport for the generated operations. Pass it as
 *  `{ client }` to any of them.
 *
 *  Most callers do not need this: the operations fall back to a
 *  module-level client, and a consumer that configures THAT one -
 *  with createResilientFetch - gets the same behaviour without
 *  naming a client at every call. Reach for this to run several
 *  clients with different policies, or against different hosts. */
export function createClient({ baseUrl, ...options }: ClientOptions) {
  const resilientFetch = createResilientFetch(options)

  // THE ADAPTER. The one place that knows which generator produced the
  // operations: it hands them a configured transport.
  const client = createGeneratedClient(createConfig({ baseUrl, fetch: resilientFetch }))

  // Keep fetch's own split between the two kinds of failure.
  //
  // An HTTP error status is an answer - 401 means re-auth, 409 means
  // conflict - so it arrives as { error } and the caller branches on
  // it. A transport failure is not an answer, so it throws. The
  // generated client returns { error } for both; `response` is
  // undefined exactly when the request never completed.
  //
  // The thrown value stays the server's parsed body rather than a
  // wrapper class, because consumers forward it onward - wrapping it
  // would put our class name into their API's error responses.
  client.interceptors.error.use((error, response) => {
    if (response === undefined) {
      throw error instanceof Error ? error : new Error('request did not complete', { cause: error })
    }
    return error
  })

  return client
}
